import Foundation
import Capacitor
import AuthenticationServices
import CryptoKit

/// Native "Sign in with Apple" (App Store guideline 4.8: required when the app also offers
/// Google/Facebook/... sign-in). The web layer calls
/// `Capacitor.Plugins.AppleSignIn.authorize({ nonce })` and receives the identity token, which
/// the BACKEND must verify (signature, audience = bundle id, nonce) before creating a session.
///
/// `nonce` is a random value generated by the web layer. Apple embeds its SHA-256 (hex) in the
/// identity token; the server recomputes it from the raw nonce, so a captured token cannot be replayed.
@objc(AppleSignInPlugin)
public class AppleSignInPlugin: CAPPlugin, CAPBridgedPlugin {
    public let identifier = "AppleSignInPlugin"
    public let jsName = "AppleSignIn"
    public let pluginMethods: [CAPPluginMethod] = [
        CAPPluginMethod(name: "authorize", returnType: CAPPluginReturnPromise)
    ]

    private var pendingCall: CAPPluginCall?
    private var controller: ASAuthorizationController?

    @objc func authorize(_ call: CAPPluginCall) {
        guard let nonce = call.getString("nonce"), !nonce.isEmpty else {
            call.reject("nonce is required")
            return
        }
        if pendingCall != nil {
            call.reject("Sign in with Apple is already in progress")
            return
        }

        let request = ASAuthorizationAppleIDProvider().createRequest()
        request.requestedScopes = [.fullName, .email]
        request.nonce = AppleSignInPlugin.sha256Hex(nonce)

        let controller = ASAuthorizationController(authorizationRequests: [request])
        controller.delegate = self
        controller.presentationContextProvider = self
        self.controller = controller
        self.pendingCall = call
        bridge?.saveCall(call)   // keep the call alive across the system sheet
        DispatchQueue.main.async { controller.performRequests() }
    }

    private func finish(_ block: (CAPPluginCall) -> Void) {
        guard let call = pendingCall else { return }
        block(call)
        bridge?.releaseCall(call)
        pendingCall = nil
        controller = nil
    }

    private static func sha256Hex(_ input: String) -> String {
        SHA256.hash(data: Data(input.utf8)).map { String(format: "%02x", $0) }.joined()
    }
}

extension AppleSignInPlugin: ASAuthorizationControllerDelegate {
    public func authorizationController(controller: ASAuthorizationController,
                                        didCompleteWithAuthorization authorization: ASAuthorization) {
        guard let credential = authorization.credential as? ASAuthorizationAppleIDCredential,
              let tokenData = credential.identityToken,
              let identityToken = String(data: tokenData, encoding: .utf8) else {
            finish { $0.reject("No identity token returned") }
            return
        }
        // fullName/email are delivered ONLY on the very first authorization: the web layer must
        // persist them then.
        var result: [String: Any] = ["identityToken": identityToken, "user": credential.user]
        if let email = credential.email { result["email"] = email }
        if let name = credential.fullName {
            result["givenName"] = name.givenName ?? ""
            result["familyName"] = name.familyName ?? ""
        }
        finish { $0.resolve(result) }
    }

    public func authorizationController(controller: ASAuthorizationController, didCompleteWithError error: Error) {
        let code = (error as? ASAuthorizationError)?.code
        // 1001 = user cancelled: report it distinctly so the UI stays silent.
        finish { $0.reject(code == .canceled ? "cancelled" : error.localizedDescription, code == .canceled ? "CANCELLED" : nil) }
    }
}

extension AppleSignInPlugin: ASAuthorizationControllerPresentationContextProviding {
    public func presentationAnchor(for controller: ASAuthorizationController) -> ASPresentationAnchor {
        return bridge?.viewController?.view.window ?? ASPresentationAnchor()
    }
}
